{
  "representation_type": "integral_representation",
  "latent_object": {
    "type": "uniform_density_on_unit_interval",
    "kernel": "exp(t z)",
    "support": "[0,1]"
  },
  "member_maps": [
    {
      "source_node_id": "G0001",
      "role": "target_integral"
    }
  ],
  "operators": [
    {
      "id": "affine_scaling",
      "action": "z -> t z"
    },
    {
      "id": "integration_over_unit_interval",
      "action": "Lebesgue integration over [0,1]"
    }
  ],
  "reconstruction_rule": "H(z) = ∫_0^1 exp(t z) dt, with H(0)=1 from the integrand value exp(0)=1.",
  "required_assumptions": [
    "exp is continuous on [0,1] × R",
    "the integral is a finite Riemann/Lebesgue integral"
  ],
  "proof_obligations": [
    "Show for z ≠ 0: ∫_0^1 exp(t z) dt = (exp(z) - 1)/z.",
    "Show for z = 0: both sides equal 1 by continuity.",
    "Show the reconstructed H is real-analytic on R."
  ]
}
